<?php
namespace Tests\Feature;
use App\Jobs\{GenerateWatermarkedVariant,ReprocessStudioWatermarks};use App\Models\{Group,MediaAsset,MediaVariant,Photo,User};use App\Support\WatermarkPosition;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\{Hash,Queue,Storage};use Illuminate\Support\Str;use Inertia\Testing\AssertableInertia as Assert;use Tests\TestCase;
class WatermarkSettingsTest extends TestCase{use RefreshDatabase;protected function setUp():void{parent::setUp();config(['media.disk'=>'private_local']);Storage::fake('private_local');}private function owner():User{return User::create(['name'=>'Owner','email'=>'watermark@test.local','password'=>Hash::make('x'),'status'=>'active','account_type'=>'photographer','plan'=>'essential']);}private function data(array$x=[]):array{return array_replace(['size_percentage'=>15,'position'=>'bottom_right','remove_logo'=>false],$x);}public function test_page_and_all_values_persist_with_validation():void{$u=$this->owner();$this->actingAs($u)->get(route('settings.watermark'))->assertInertia(fn(Assert$p)=>$p->component('Settings/Watermark')->where('settings.size_percentage',15)->where('settings.position','bottom_right'));foreach(WatermarkPosition::VALUES as$pos)$this->put(route('settings.watermark.update'),$this->data(['size_percentage'=>99,'position'=>$pos]))->assertSessionHasNoErrors();$this->put(route('settings.watermark.update'),$this->data(['size_percentage'=>0]))->assertSessionHasErrors('size_percentage');$this->put(route('settings.watermark.update'),$this->data(['size_percentage'=>100]))->assertSessionHasErrors('size_percentage');$this->put(route('settings.watermark.update'),$this->data(['position'=>'left-top']))->assertSessionHasErrors('position');}
public function test_logo_upload_replace_remove_is_private_and_queues_regeneration():void{Queue::fake();$u=$this->owner();$this->actingAs($u)->put(route('settings.watermark.update'),$this->data(['logo'=>UploadedFile::fake()->image('mark.png',200,80)]))->assertSessionHasNoErrors();$s=$u->watermarkSetting()->first();$first=$s->logo_object_key;Storage::disk('private_local')->assertExists($first);$this->get(route('settings.watermark.logo'))->assertOk()->assertHeader('Content-Type','image/png');$this->get(route('settings.watermark'))->assertInertia(fn(Assert$p)=>$p->missing('settings.logo_object_key')->where('settings.has_logo',true));Queue::assertPushed(ReprocessStudioWatermarks::class);$this->put(route('settings.watermark.update'),$this->data(['logo'=>UploadedFile::fake()->image('new.jpg',200,80)]))->assertSessionHasNoErrors();Storage::disk('private_local')->assertMissing($first);$new=$s->fresh()->logo_object_key;Storage::disk('private_local')->assertExists($new);$this->put(route('settings.watermark.update'),$this->data(['remove_logo'=>true]))->assertSessionHasNoErrors();Storage::disk('private_local')->assertMissing($new);}
public function test_invalid_oversized_and_corrupted_logos_are_rejected():void{$u=$this->owner();$this->actingAs($u)->put(route('settings.watermark.update'),$this->data(['logo'=>UploadedFile::fake()->create('x.svg',2,'image/svg+xml')]))->assertSessionHasErrors('logo');$this->put(route('settings.watermark.update'),$this->data(['logo'=>UploadedFile::fake()->create('x.png',2049,'image/png')]))->assertSessionHasErrors('logo');$p=tempnam(sys_get_temp_dir(),'wm-');file_put_contents($p,'bad');$this->put(route('settings.watermark.update'),$this->data(['logo'=>new UploadedFile($p,'x.png','image/png',null,true)]))->assertSessionHasErrors('logo');}
public function test_position_coordinates_remain_inside_portrait_landscape_and_square():void{foreach([[1200,800],[800,1200],[900,900]]as[$w,$h])foreach(WatermarkPosition::VALUES as$p){[$x,$y]=WatermarkPosition::coordinates($p,$w,$h,180,60);$this->assertGreaterThanOrEqual(0,$x);$this->assertGreaterThanOrEqual(0,$y);$this->assertLessThanOrEqual($w-180,$x);$this->assertLessThanOrEqual($h-60,$y);}}
public function test_job_creates_separate_versioned_variant_without_modifying_original():void{$u=$this->owner();$logo=UploadedFile::fake()->image('mark.png',200,80);$this->actingAs($u)->put(route('settings.watermark.update'),$this->data(['logo'=>$logo,'size_percentage'=>20,'position'=>'center']));$g=Group::create(['name'=>'G','creator_id'=>$u->id,'watermark_enabled'=>true]);$source=$this->jpeg(800,600);$key='media/optimized/source.jpg';Storage::disk('private_local')->put($key,$source);$p=Photo::create(['group_id'=>$g->id,'uploader_id'=>$u->id,'filename'=>'a.jpg','original_filename'=>'a.jpg','path'=>$key]);$a=MediaAsset::create(['uuid'=>(string)Str::uuid(),'photo_id'=>$p->id,'group_id'=>$g->id,'owner_id'=>$u->id,'uploader_id'=>$u->id,'storage_disk'=>'private_local','original_object_key'=>'media/original/master.jpg','original_filename'=>'a.jpg','mime_type'=>'image/jpeg','size_bytes'=>strlen($source),'checksum_sha256'=>hash('sha256',$source),'state'=>'completed']);Storage::disk('private_local')->put('media/original/master.jpg','immutable-master');MediaVariant::create(['media_asset_id'=>$a->id,'variant_type'=>'optimized','storage_disk'=>'private_local','object_key'=>$key,'mime_type'=>'image/jpeg','size_bytes'=>strlen($source),'checksum_sha256'=>hash('sha256',$source),'width'=>800,'height'=>600,'state'=>'ready']);(new GenerateWatermarkedVariant($a->id,$u->watermarkSetting->settings_version))->handle(app(\App\Contracts\ProtectedMediaStorage::class));$v=$a->variants()->where('variant_type','watermarked')->firstOrFail();Storage::disk('private_local')->assertExists($v->object_key);$this->assertSame('immutable-master',Storage::disk('private_local')->get('media/original/master.jpg'));$this->assertSame($u->watermarkSetting->settings_version,$v->version);}
private function jpeg(int$w,int$h):string{$im=imagecreatetruecolor($w,$h);imagefill($im,0,0,imagecolorallocate($im,80,100,120));ob_start();imagejpeg($im,null,90);$b=ob_get_clean();imagedestroy($im);return$b;}}
